1	'use client'
2	
3	import { WeekGridColumn } from './WeekGridColumn'
4	import type { DaySchedule, DayOfWeek, ScheduleSlot } from './types'
5	
6	interface WeekGridProps {
7	  slots: ScheduleSlot[]
8	  onAddSlot: (dayOfWeek: DayOfWeek, startTime: string, endTime: string) => void
9	  onDeleteSlot: (id: string) => void
10	  disabled?: boolean
11	}
12	
13	const ALL_DAYS: DayOfWeek[] = [0, 1, 2, 3, 4, 5, 6]
14	
15	export function WeekGrid({ slots, onAddSlot, onDeleteSlot, disabled }: WeekGridProps) {
16	  // Group slots by day_of_week
17	  const days: DaySchedule[] = ALL_DAYS.map((dayOfWeek) => ({
18	    dayOfWeek,
19	    slots: slots.filter((s) => s.day_of_week === dayOfWeek),
20	  }))
21	
22	  return (
23	    <div className="grid grid-cols-7 gap-2 min-w-0 overflow-x-auto">
24	      {days.map((day) => (
25	        <WeekGridColumn
26	          key={day.dayOfWeek}
27	          day={day}
28	          onAddSlot={onAddSlot}
29	          onDeleteSlot={onDeleteSlot}
30	          disabled={disabled ?? false}
31	        />
32	      ))}
33	    </div>
34	  )
35	}
